#dm-elem-s0 { position: absolute; top: 36%; left: 50%; transform: translate(-50%, -50%); display: flex; flex-direction: column; align-items: center; pointer-events: none; z-index: 40; perspective: 1200px; background: transparent !important; }
#dm-elem-s0 .dm-3d-card { position: relative; display: flex; flex-direction: column; align-items: center; transform-style: preserve-3d; transform: perspective(1200px) rotateX(-14deg) rotateY(10deg); }
#dm-elem-s0 .dm-lens-flare { position: absolute; top: 110px; left: 50%; transform: translate(-50%, -50%) scaleX(0); width: 280px; height: 3.5px; background: linear-gradient(90deg, transparent 0%, rgba(255,255,255,0.95) 50%, transparent 100%); box-shadow: 0 0 18px #FFD700, 0 0 35px #FFA000; border-radius: 50%; z-index: 45; }
#dm-elem-s0 .dm-particles-field { position: absolute; inset: -30px; pointer-events: none; }
#dm-elem-s0 .dm-ember { position: absolute; width: 4px; height: 4px; border-radius: 50%; background: #FFD700; box-shadow: 0 0 8px #FFA000, 0 0 14px #FFE082; opacity: 0; }
#dm-elem-s0 .dm-ember.e1 { top: 70%; left: 30%; } #dm-elem-s0 .dm-ember.e2 { top: 65%; left: 68%; } #dm-elem-s0 .dm-ember.e3 { top: 80%; left: 45%; } #dm-elem-s0 .dm-ember.e4 { top: 50%; left: 20%; } #dm-elem-s0 .dm-ember.e5 { top: 55%; left: 80%; } #dm-elem-s0 .dm-ember.e6 { top: 85%; left: 60%; }
#dm-elem-s0 .dm-astra-svg { filter: drop-shadow(0 0 25px rgba(255, 215, 0, 0.85)); }
#dm-elem-s0 .dm-astra-label { margin-top: 14px; display: flex; flex-direction: column; align-items: center; text-align: center; }
#dm-elem-s0 .dm-astra-title { font-size: 26px; font-weight: 800; color: #FFE082; letter-spacing: 0.08em; text-shadow: 0 0 16px rgba(255, 215, 0, 0.9), 0 2px 8px rgba(0, 0, 0, 0.9); }
#dm-elem-s0 .dm-astra-sub { font-size: 13px; font-weight: 600; color: rgba(255, 255, 255, 0.8); letter-spacing: 0.12em; text-transform: uppercase; text-shadow: 0 1px 4px rgba(0, 0, 0, 0.8); }

render.js:
// Dynamic Motion Graphic Animation (AI Generated): dm-elem-s0
{
  const subTl = gsap.timeline();
  const el = document.getElementById("dm-elem-s0") || document.querySelector("#dm-elem-s0") || document.querySelector(".dynamic-motion-visual");
  if (el) {
    gsap.set(el, { opacity: 0, pointerEvents: "none" });
    try {
      (function(tl, el) {

        tl.fromTo(el, { opacity: 0 }, { opacity: 1, duration: 0.8 });
        const card = el.querySelector(".dm-3d-card");
        if (card) {
          tl.fromTo(card, { scale: 0.88, opacity: 0 }, { scale: 1, opacity: 1, duration: 1.0, ease: "power2.out" }, "<");
        }
        const flare = el.querySelector(".dm-lens-flare");
        if (flare) {
          tl.fromTo(flare, { scaleX: 0, opacity: 0 }, { scaleX: 1.6, opacity: 1, duration: 0.4, ease: "power3.out" }, 0.2);
          tl.to(flare, { scaleX: 0.6, opacity: 0.3, duration: 0.6, ease: "power2.inOut" }, 0.6);
        }
        const embers = el.querySelectorAll(".dm-ember");
        if (embers && embers.length > 0) {
          embers.forEach((em, idx) => {
            tl.fromTo(em, { opacity: 0, y: 0, scale: 0.5 }, { opacity: 0.9, y: -60 - (idx * 15), scale: 1.2, duration: 2.2 + (idx * 0.3), ease: "power1.out", repeat: 3, stagger: 0.2 }, 0.3);
          });
        }
        tl.to(el.querySelectorAll(".dm-ring-cw"), { rotation: 360, duration: 8, ease: "none", repeat: 5, transformOrigin: "center center" }, 0);
        tl.to(el.querySelectorAll(".dm-ring-ccw"), { rotation: -360, duration: 6, ease: "none", repeat: 6, transformOrigin: "center center" }, 0);
        tl.to(el.querySelectorAll(".dm-pulse-ring"), { scale: 1.25, opacity: 0, duration: 2.4, repeat: 2, ease: "power1.out", transformOrigin: "center center" }, 0);
        tl.to(el.querySelectorAll(".dm-core-glow"), { scale: 1.15, repeat: 2, yoyo: true, duration: 2.2, ease: "sine.inOut", transformOrigin: "center center" }, 0);

      })(subTl, el);
    } catch(err) {
      console.warn("Error running custom motion JS:", err);
    }

    // Normalize start time so subTl always starts at 0 internally
    const children = subTl.getChildren();
    if (children && children.length > 0) {
      const minStart = Math.min(...children.map((c: any) => c.startTime()));
      if (minStart > 0 && Number.isFinite(minStart)) {
        subTl.shiftChildren(-minStart, true);
      }
    }

    const effDur = Math.max(2.0, subTl.duration() || 4.5);
    subTl.to(el, { opacity: 0, duration: 0.6, ease: "power2.in" }, Math.max(0.5, effDur - 0.6));
    tl.add(subTl, 1.2);
  }
}

